parameters.jsonBody:
={{ JSON.stringify({
  keyword: $json.keyword,
  dmMessages: [$json.dmMessage],
  commentReplies: $json.publicReply ? [$json.publicReply] : [],
  publicReplyEnabled: Boolean($json.publicReply),
  scope: $json.target === 'all_posts' ? 'global' : 'post_specific',
  includeNextPost: $json.target !== 'all_posts'
}) }}
